var state = {
  rpm: "102",          // "102" = Power Check atual · "100" = pairado (gráfico RFM 4D)
  config: "NONE",
  torqueRef: "T95",          // padrão: 95%
  altitudeAbs: "",
  altitudeSign: "pos",
  oat: "",
  ng1: "", itt1: "", ng2: "", itt2: "",
  registration: "",
  dateTime: "",
  result: null,
  reportHtml: null,
};

var CONFIGS = [
  { key: "NONE", label: "IBF/EAPS Não Instalado" },
  { key: "IBF", label: "IBF Installed" },
  { key: "EAPS", label: "EAPS Installed" },
];
var TORQUES = [
  { key: "T90", label: "90%" },
  { key: "T95", label: "95%" },
];

// ---------------------------------------------------------------------------
// RENDER: seção 01 - configuração
// ---------------------------------------------------------------------------
function renderConfigOptions() {
  var el = document.getElementById("configOptions");
  el.innerHTML = "";
  CONFIGS.forEach(function (c) {
    var btn = document.createElement("button");
    btn.className = "pc-seg-btn pc-cfg-btn" + (state.config === c.key ? " is-active" : "");
    // RPM 100%: não há gráfico de pairado para IBF -> botão desabilitado
    if (state.rpm === "100" && c.key === "IBF") { btn.disabled = true; btn.classList.add("is-disabled"); btn.title = T("Sem gráfico de pairado (100%) para IBF", "No hover (100%) chart for IBF"); }
    btn.textContent = c.label;
    btn.addEventListener("click", function () {
      state.config = c.key;
      renderConfigOptions();
      renderConfigTag();
    });
    el.appendChild(btn);
  });
}

function renderTorqueOptions() {
  var el = document.getElementById("torqueOptions");
  el.innerHTML = "";
  TORQUES.forEach(function (t) {
    var btn = document.createElement("button");
    btn.className = "pc-seg-btn pc-tq-btn" + (state.torqueRef === t.key ? " is-active" : "");
    btn.textContent = t.label;
    btn.addEventListener("click", function () {
      state.torqueRef = t.key;
      renderTorqueOptions();
      renderConfigTag();
      if (state.rpm === "100") fillHoverTq(true);
    });
    el.appendChild(btn);
  });
}

// ordem na tela: 100% à esquerda, 102% à direita (102% continua sendo o padrão)
var RPMS = [
  { key: "100", label: "100 %" },
  { key: "102", label: "102 %" },
];

function renderRpmOptions() {
  var el = document.getElementById("rpmOptions");
  el.innerHTML = "";
  RPMS.forEach(function (r) {
    var btn = document.createElement("button");
    btn.type = "button";
    btn.className = "pc-seg-btn pc-rpm-btn" + (state.rpm === r.key ? " is-active" : "");
    btn.textContent = r.label;
    btn.addEventListener("click", function () { setRpm(r.key); });
    el.appendChild(btn);
  });
}

// 100%: o torque de referência (90/95%) preenche o "TQ lido" dos dois motores
// (campos continuam editáveis). force = sobrescreve; senão só preenche vazios.
function torqueRefValue() { return state.torqueRef === "T95" ? "95" : "90"; }
function fillHoverTq(force) {
  ["hTq1", "hTq2"].forEach(function (id) {
    var el = document.getElementById(id);
    if (force || el.value.trim() === "") el.value = torqueRefValue();
  });
}

// troca entre o formulário 102% e o de pairado 100% (cada um guarda seus dados)
function setRpm(key) {
  if (state.rpm === key) return;
  state.rpm = key;
  var is100 = key === "100";
  if (is100) fillHoverTq(false);
  if (is100 && state.config === "IBF") state.config = "NONE";
  renderConfigOptions();
  document.getElementById("sec102").style.display = is100 ? "none" : "";
  document.getElementById("sec100").style.display = is100 ? "" : "none";
  state.result = null;
  document.getElementById("resultSection").style.display = "none";
  closeReport();
  renderRpmOptions();
  renderConfigTag();
}

function renderConfigTag() {
  var el = document.getElementById("configTag");
  if (state.rpm === "100") { el.textContent = DATA[state.config].label + " · Torque " + torqueRefValue() + "% · " + HOVER_TXT; return; }
  var torqueLabel = state.torqueRef === "T90" ? "90%" : "95%";
  el.textContent = DATA[state.config].label + " · Torque " + torqueLabel;
}

// ---------------------------------------------------------------------------
// Campo de altitude com sinal (POS/NEG)
// ---------------------------------------------------------------------------
// O sinal agora é digitado no próprio campo pelo atalho ± (como no CAT B e no W.A.T).
function updateSignButton() { /* sem estado visual: o "-" aparece no campo */ }

function syncAltitudeFromInput() {
  var el = document.getElementById("altitudeAbs");
  var raw = el.value;
  var neg = raw.trim().charAt(0) === "-";
  var abs = raw.replace(/[^0-9.,]/g, "");
  el.value = (neg ? "-" : "") + abs;
  state.altitudeAbs = abs;
  state.altitudeSign = neg ? "neg" : "pos";
}

document.getElementById("altitudeAbs").addEventListener("input", syncAltitudeFromInput);

document.getElementById("signBtn").addEventListener("click", function () {
  var el = document.getElementById("altitudeAbs");
  var v = el.value.trim();
  el.value = v.charAt(0) === "-" ? v.slice(1) : "-" + v;
  syncAltitudeFromInput();
  el.focus();
});

